@end
@implementation VolumeCell
-(void)drawBarInside:(NSRect)rect flipped:(BOOL)flipped{NSRect b=self.controlView.bounds;CGFloat x=7,width=b.size.width-14,y=NSMidY(b)-1.5;[[NSColor.labelColor colorWithAlphaComponent:0.25]setFill];[[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(x,y,width,3) xRadius:1.5 yRadius:1.5]fill];[[NSColor.labelColor colorWithAlphaComponent:self.enabled?1:0.4]setFill];CGFloat fraction=(self.doubleValue-self.minValue)/MAX(1,self.maxValue-self.minValue);[[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(x,y,width*MAX(0,MIN(1,fraction)),3) xRadius:1.5 yRadius:1.5]fill];}
