@interface CardView:NSView
@end
@implementation CardView
-(BOOL)isFlipped{return YES;}
-(void)viewDidChangeEffectiveAppearance{[super viewDidChangeEffectiveAppearance];self.needsDisplay=YES;for(NSView*v in self.subviews){v.needsDisplay=YES;if([v isKindOfClass:NSImageView.class])v.layer.backgroundColor=NSColor.quaternaryLabelColor.CGColor;}}
